  downloadURI(uri, name) {
    const fileName = uri; // The file name you want to download
    this.downloadFile(fileName).subscribe(
      (blob) => {
        const a = document.createElement('a');
        const objectUrl = URL.createObjectURL(blob);
        a.href = objectUrl;
        a.download = name;
        a.click();
        URL.revokeObjectURL(objectUrl);
      },
      (error) => {
        console.error('Download error:', error);
      }
    );
  }


  downloadFile(cPath: string): Observable<Blob> {
    let params = new HttpParams()
    params = params.set('cPath', cPath);
    const headers = new HttpHeaders().set('Content-Type', 'application/json');

    return this.http.get(`${environment.cloudUrl}${environment.coreservice}/caseactivity/download`, {
      params: params,
      headers: headers,
      responseType: 'blob' // Important to specify blob as the response type
    });
  }


