import { Component, ViewChild, OnInit, AfterViewInit } from '@angular/core';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { ActivatedRoute } from '@angular/router';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { CaseactivityService } from '../../../services/caseactivity/caseactivity.service';
import { MatDialog } from '@angular/material/dialog';
import { ScanPaginationComponent } from '../scan-pagination/scan-pagination.component';
import { CommonModule, Location } from '@angular/common';
import { CdkVirtualScrollViewport, ScrollingModule } from '@angular/cdk/scrolling';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { HeaderService } from '../../../../core/services/header/header.service';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-case-activity',
  standalone: true,
  imports: [CommonModule, IconComponent, MatSelectModule, FormsModule, AvatarComponent, ButtonComponent,
    ScrollingModule, NgScrollbarModule
  ],
  templateUrl: './case-activity.component.html',
  styleUrl: './case-activity.component.scss'
})
export class CaseActivityComponent implements OnInit, AfterViewInit {
  @ViewChild(CdkVirtualScrollViewport) viewport: CdkVirtualScrollViewport;
  loading: boolean = false;
  limit: number = 30; Lpageno: number = 0;
  selected: any;
  selectedview: string[] = [];


  categories = [
    { name: 'RT/Presentation Connection', value: 'C' },
    { name: 'eBundle Workspace Setup', value: 'W' },
  ]

  dateCategory = [
    { value: 'N', key: 'Today' },
    { value: 'W', key: 'This Week' },
    { value: 'M', key: 'This Month' }
  ]


  userList = [];
  nCaseid: string = null;
  casename: string;
  caselist: any = [];
  userlist: any = [];
  userLoglist: any = [];
  sessionlist: any = [];
  nUserid: string = null;
  nSesid: number = 0;
  cLogtype: string = 'L';
  datetype: string = 'N';
  daterange: any = { start: new Date(), end: new Date() };
  activeSession: any = {}; connectionTeam: any = [];
  connectionData: any = []; connectionDetail: any = {};
  nTeamid: number = 0;
  fileTypes: any = []; bundleData: any = {}; scanData: any = {};
  assignStorage: number = 214748364800;//2GB //107374182400; //1GB
  storagesize: any = { value: 0, sizes: 'Bytes' };
  usedpercentage: any = 0;
  selecteduser: any = {};
  downloading: boolean = false;
  loadingstorage: boolean = false;
  fileSize: any;
  constructor(private route: ActivatedRoute, private caseactivityService: CaseactivityService, private dialog: MatDialog,
    private localtion: Location, private readonly cm: CommonfunctionService, private userPermissions: UserPermissionService
  ) {
    var params = this.route.snapshot.params;

    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;
    userPermissions.userPermissionList(this.nCaseid);
  }

  ngOnInit() {
    this.storagesize = this.formatBytes(this.assignStorage);
    this.getCaselist();
    if (this.nCaseid) {
      this.getUserlist();
      this.getsessionlist();
      this.geteBundleData();
      this.geteScandata();
      this.geteStoragedata();
    }
    // this.scan();
  }

  ngAfterViewInit() {
    setTimeout(() => {
      this.selectedview = ["RT/Presentation Connection", "eBundle Workspace Setup"];
    });
  }

  goBack() {
    this.localtion.back();
  }

  async getCaselist() {
    const res = await this.caseactivityService.getCaseLS()
    if (res && res.length) {
      this.caselist = res;
      if (this.nCaseid)
        this.casename = this.caselist.find(e => e.nCaseid == this.nCaseid)?.cCasename;
    }
  }


  selectAll() {
    this.selectedview = this.categories.map(e => e.name);
  }

  changeCase() {
    this.getUserlist();
    this.getsessionlist();
    this.geteBundleData();
    this.geteScandata();
    this.geteStoragedata();
  }

  async getUserlist() {
    this.userList = [];
    this.userLoglist = [];
    const res = await this.caseactivityService.getUserLS(this.nCaseid)
    if (res && res.length) {
      this.userList = res;
      this.userList[0]['isSelected'] = true;
      this.selectUser(this.userList[0]);
      // this.getUserLog(1);
    } else {
      this.userList = [];
      this.userLoglist = [];
    }
  }


  selectUser(x) {
    this.userList.forEach(e => {
      if (e.nUserid != x.nUserid) {
        e.isSelected = false;
      }
    });
    if (x.nUserid != this.nUserid) {
      x.isSelected = true;
      this.selecteduser = x;
      this.nUserid = x.nUserid;
      this.getUserLog(1);
    }
  }


  async getUserLog(pageno: number = 1) {
    this.Lpageno = pageno;
    const res = await this.caseactivityService.getUserLog(this.nCaseid, this.nUserid, this.cLogtype, pageno, this.daterange)
    this.userLoglist = res;
  }

  changeDateType() {
    const currentDate = new Date();
    if (this.datetype == 'N') {
      this.daterange = { start: currentDate, end: currentDate };
    } else if (this.datetype == 'W') {
      this.daterange = { start: new Date(currentDate.getFullYear(), currentDate.getMonth(), currentDate.getDate() - (currentDate.getDay() + 2)), end: currentDate };
    } else if (this.datetype == 'M') {
      this.daterange = { start: new Date(currentDate.getFullYear(), currentDate.getMonth(), 1), end: currentDate };
    }

  }


  scrolled(ev) {
    const end = this.viewport.getRenderedRange().end;
    const total = this.viewport.getDataLength();
    if (this.loading) { return }
    if (end === total) {
      var pageno = total / this.limit + 1;
      if (pageno % 1 || (pageno < this.userLoglist.length / this.limit)) { return }
      if (this.Lpageno == pageno) { return };
      this.getUserLog(pageno)
    }
  }

  scan(): void {
    const dialogRef = this.dialog.open(ScanPaginationComponent, {
      width: '100%',
      height: '100%',
      panelClass: ['noroundedandshadow', 'nobackground'],
    });
    dialogRef.componentInstance.nCaseid = this.nCaseid;
    dialogRef.componentInstance.casename = this.casename;

    dialogRef.afterClosed().subscribe(() => {
      this.geteScandata();
    });
  }

  trackById(index: number, item: any) {
    return item;
  }



  async getsessionlist() {
    this.sessionlist = [];
    this.connectionTeam = [];
    this.connectionData = [];
    this.nTeamid = null;
    this.connectionDetail = {};
    const res = await this.caseactivityService.getSession(this.nCaseid)
    if (res && res.length) {
      this.sessionlist = res;
      this.activeSession = this.sessionlist[0];
      this.getConnection();
    } else {
      this.sessionlist = [];
    }
  }

  async getConnection() {
    this.connectionTeam = [];
    this.connectionData = [];
    this.nTeamid = null;
    this.connectionDetail = {};
    const res = await this.caseactivityService.getConnection(this.nCaseid, this.activeSession.nSesid)
    // this.userLoglist = res;
    if (res && res.length) {
      this.connectionTeam = res[0];
      this.connectionData = res[1];
      this.nTeamid = this.connectionTeam && this.connectionTeam.length ? this.connectionTeam[0].nTeamid : [];
      this.getTeamConnection();
    }
  }

  getTeamConnection() {
    const ind = this.connectionData.findIndex(e => e.nTeamid == this.nTeamid);
    if (ind > -1) {
      this.connectionDetail = this.connectionData[ind];
    } else {
      this.connectionDetail = {};
    }
  }

  goToRealtimeLog() {
    this.cm.goto('realtimelog', { id: this.nCaseid })
  }

  async geteBundleData() {
    this.fileTypes = [];
    this.bundleData = {};
    const res = await this.caseactivityService.getBundleDetail(this.nCaseid)
    if (res && res.length) {
      this.fileTypes = res[0];
      this.bundleData = res[1] && res[1].length ? res[1][0] : {};
    } else {
      this.fileTypes = [];
      this.bundleData = {};
    }
  }


  async geteScandata() {
    this.usedpercentage = 0;
    this.scanData = [];
    const res = await this.caseactivityService.geteScandata(this.nCaseid)
    if (res && res.length) {
      this.scanData = res[0];
      this.scanData['dDays'] = this.getDifferenceInDays(this.scanData?.dCaseCreateDt ? this.scanData?.dCaseCreateDt : new Date())
    } else {
      this.scanData = [];
    }
  }
  async geteStoragedata() {
    this.loadingstorage = true;
    this.usedpercentage = 0;
    this.fileSize = this.formatBytes(0);
    const res = await this.caseactivityService.geteStoragedata(this.nCaseid)
    this.loadingstorage = false;
    if (res && res?.msg == 1) {
      this.fileSize = this.formatBytes(res.totalSize);
      this.usedpercentage = this.calculateStorageUsage(res.totalSize, this.assignStorage);
    } else {
    }
  }


  formatBytes(bytes) {
    if (bytes === 0) return '0 Bytes';

    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(1024)); // Find the index for the size
    const value = bytes / Math.pow(1024, i); // Calculate the value in the appropriate unit

    return { value: value.toFixed(2), sizes: sizes[i] }; // Return the value with 2 decimal points
  }

  calculateStorageUsage(usedSize, totalSize) {
    if (totalSize === 0) {
      return 'Total size cannot be zero';
    }
    const percentage = (usedSize / totalSize) * 100;

    return percentage.toFixed(2); // Format the result to 2 decimal points
  }

  async DownloadExcel() {
    this.downloading = true;
    const res = await this.caseactivityService.downloadScanDetail(this.nCaseid, null, '{}')
    // this.userLoglist = res;
    debugger;
    this.downloading = false;
    if (res && res.msg == 1) {
      let filename = this.replaceSpecialChars(`Paginated_file_${this.casename}`)
      this.caseactivityService.downloadURI(res.cPath, `${filename}.xlsx`);
    }
  }

  getDifferenceInDays(dateString: string): number {
    const givenDate = new Date(dateString);
    const currentDate = new Date();

    // Calculate the difference in milliseconds
    const diffTime = currentDate.getTime() - givenDate.getTime();

    // Convert milliseconds to days
    return Math.floor(diffTime / (1000 * 60 * 60 * 24));
  }

  replaceSpecialChars(str) {
    return str.replace(/[^a-zA-Z0-9]/g, '_');
  }

}
