import { ChangeDetectorRef, Component, ViewChild } from '@angular/core';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { FoldersComponent } from '../../../../shared/components/myfiles/folders/folders.component';
import { SectionRes } from '../../../interfaces/bundlemanage.interface';
import { MatDialog } from '@angular/material/dialog';
import { SectionComponent } from '../../../../shared/components/myfiles/section/section.component';
import { CommonModule } from '@angular/common';
import { MatTooltipModule } from '@angular/material/tooltip';
import { CaseactivityService } from '../../../services/caseactivity/caseactivity.service';
import { HeaderService } from '../../../../core/services/header/header.service';
import { Subscription } from 'rxjs';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { paginateNonPaginatedData, paginationSocketRes } from '../../../interfaces/pagination.interface';
import { PaginationService } from '../../../services/pagination/pagination.service';
import { TruncateTooltipDirective } from '../../../../shared/directive/truncate-tooltip.directive';

@Component({
  selector: 'app-scan-pagination',
  standalone: true,
  imports: [CommonModule, ButtonComponent, IconComponent, FoldersComponent, SectionComponent, MatTooltipModule, TruncateTooltipDirective],
  templateUrl: './scan-pagination.component.html',
  styleUrl: './scan-pagination.component.scss'
})
export class ScanPaginationComponent {
  @ViewChild('folderCom') folderCom: FoldersComponent;
  sStatus: string = 'S';
  pStatus: string = 'S';
  progress: number = 0;
  isadmin: true;
  activeSection: SectionRes; cFoldertype: string;
  nCaseid: string; nBundleid: string;
  nSelectedFolderid: any = [];
  brdcrumb: any = [];
  isWholeCase: boolean = false;
  scanning: boolean = false; downloading: boolean = false;
  scanResult: any = {};
  casename: string;
  paginating: boolean = false;
  socketSubscription: Subscription;
  constructor(private dialog: MatDialog, private readonly cdr: ChangeDetectorRef,
    private caseactivityService: CaseactivityService, public cf: CommonfunctionService,
    private ss: SocketService, private paginationS: PaginationService) {
    this.socketSubscription = this.ss.getPagination().subscribe((res: any) => {
      const data: paginationSocketRes = res?.data?.data || [];
      if (data && data.nCaseid == this.nCaseid) {
        console.log('pagination data', data);
        if (data.cStatus == 'P') {
          this.cf.paginationdata = data;
          this.progress = Number(this.calcCompPprogres(cf.paginationdata.comp_progres, cf.paginationdata.total_prog));
          if (!this.cf.isPagination) {
            this.cf.isPagination = true;
          }
        }
        if (data.cStatus == 'C') {
          this.progress = 100;
          this.paginating = false;
          this.pStatus = 'S';
          this.cf.isPagination = false;
          this.cf.paginationdata = {};
        } if (data.cStatus == 'S') {
          this.progress = 100;
          this.paginating = false;
          this.pStatus = 'S';
          this.cf.isPagination = false;
          this.cf.paginationdata = {};
        }
      }
    })

  }
  ngOnInit() {
  }


  scan() {
    if (this.scanning) return;
    this.sStatus = 'R';
    this.getScanData();
    this.updateProg();
  }

  updateProg() {
    this.progress = 0;
    const startTime = Date.now();
    const duration = 5000; // 10 seconds

    const updateProgress = () => {
      const elapsed = Date.now() - startTime;
      const progressValue = Math.min((elapsed / duration), 1);
      this.progress = Math.floor(progressValue * 100);
      if (elapsed < duration) {
        requestAnimationFrame(updateProgress);
      } else {
        if (!this.scanning) {
          this.progress = 100;
          this.sStatus = 'C';
        } else {
          this.progress = 0;
          updateProgress();
        }
      }
    };

    requestAnimationFrame(updateProgress);
  }

  async getScanData() {
    this.scanning = true;
    let jBundles: string = '{}';
    debugger
    if (this.nSelectedFolderid.length > 0) {
      jBundles = `{${this.nSelectedFolderid.map((x) => x.id)}}`;
    }
    const res = await this.caseactivityService.scanPaginateData(this.nCaseid, this.activeSection?.nSectionid ? this.activeSection?.nSectionid : null, jBundles);
    this.scanning = false;
    this.scanResult = res[0];
  }


  close() {
    this.dialog.closeAll();
  }

  changeFolder(event) {
    console.log('CHANGE FOLDER', event)
    if (event["brdcrumb"]) {
      if (event["brdcrumb"].length) {
        this.brdcrumb = event["brdcrumb"];
        this.nBundleid = this.brdcrumb.length ? this.brdcrumb[this.brdcrumb.length - 1]["nBundleid"] : 0;
      } else {
        this.brdcrumb = [];
        this.nBundleid = null;
      }
      return;
    }
    if (event == 'SELECTED') {
      this.updateSelectedFiles();
    }
  }

  getsection() {

  }

  async changeSection(x) {

    this.activeSection = x;
    this.activeSection = x;
    this.cFoldertype = x.cFoldertype;
    this.cdr.detectChanges();
  }


  changeBrdcrumb(index) {
    this.brdcrumb = this.brdcrumb.filter((e, i) => i <= index);
    this.nBundleid = this.brdcrumb.length ? this.brdcrumb[this.brdcrumb.length - 1]["nBundleid"] : 0;
    // this.changeFTab();
  }

  async updateSelectedFiles(): Promise<boolean> {
    let selectedFIds: Array<{ id: string, pid: string }> = [];
    let removeFids: string[] = []
    try {

      // }
      selectedFIds = this.folderCom.TREE_DATA.filter(e => e['cIscheck'] && selectedFIds.length ? selectedFIds.some(i => i.id == e.nBundleid) : e['cIscheck']).map(({ nBundleid, nParentBundleid }) => ({ id: nBundleid, pid: nParentBundleid }));

      this.nSelectedFolderid = [...this.nSelectedFolderid, ...selectedFIds]
      removeFids = this.folderCom.TREE_DATA.filter(e => !e['cIscheck']).map(e => e.nBundleid);
      // var pids = this.nSelectedFolderid.filter(e => removeFids.some(i => i == e.id)).map(e => e.pid)
      // removeFids = [...removeFids, ...pids]
      this.nSelectedFolderid = this.nSelectedFolderid.filter(x => !removeFids.includes(x.id));

      // Get all bundle IDs from TREE_DATA for validation
      const validBundleIds = this.folderCom.TREE_DATA.map(e => e.nBundleid);
      // Filter this.nSelectedFolderid
      this.nSelectedFolderid = this.nSelectedFolderid.filter(folder => {
        // If parent exists in nSelectedFolderid and current id not in validBundleIds, remove it
        if (folder.pid && this.nSelectedFolderid.some(f => f.id === folder.pid)) {
          return validBundleIds.includes(folder.id);
        }
        return true; // Keep all other items
      });
      this.nSelectedFolderid = this.nSelectedFolderid.filter(
        (value, index, self) =>
          index === self.findIndex((t) => t.id === value.id && t.pid === value.pid)
      );

      this.cdr.detectChanges();
      return true;
    } catch (error) {
      console.error('File selection error', error)
      return false;
    }
    // }
  }

  async downLoadScandetail() {
    if (this.downloading) { this.downloading }
    this.downloading = true;
    let jBundles: string = '{}';
    debugger
    if (this.nSelectedFolderid.length > 0) {
      jBundles = `{${this.nSelectedFolderid.map((x) => x.id)}}`;
    }
    let res = await this.caseactivityService.downloadScanDetail(this.nCaseid, this.activeSection?.nSectionid ? this.activeSection?.nSectionid : null, jBundles);
    this.downloading = false;
    if (res.msg == 1) {
      let filename = this.replaceSpecialChars(`Paginated_file_${this.casename}`)
      this.caseactivityService.downloadURI(res.cPath, `${filename}.xlsx`);
    }

  }


  replaceSpecialChars(str) {
    return str.replace(/[^a-zA-Z0-9]/g, '_');
  }

  async PaginateNonPaginatedFiles() {
    var model: paginateNonPaginatedData = {
      nSectionid: this.activeSection?.nSectionid ? this.activeSection?.nSectionid : null,
      nCaseid: this.nCaseid
    };
    let res: boolean = await this.paginationS.paginateNonPaginated(model);
    if (res) {
      this.pStatus = 'R';
      this.updatePaginationProg();
    } else {
      this.pStatus = 'S';
      this.paginating = false;
    }
  }


  async updatePaginationProg() {
    this.progress = 0;
    const startTime = Date.now();
    const duration = 5000; // 10 seconds

    const updateProgress = () => {
      const elapsed = Date.now() - startTime;
      // const progressValue = Math.min((elapsed / duration), 1);
      // this.progress = Math.floor(progressValue * 100);
      if (this.pStatus == 'R') {
        requestAnimationFrame(updateProgress);
      } else {
        if (!this.paginating) {
          this.progress = 0;
          this.pStatus = 'S';
          this.scan()
        } else {
          this.progress = 0;
          updateProgress();
        }
      }
    };

    requestAnimationFrame(updateProgress);
  }

  calcCompPprogres(completedFiles, totalFiles) {
    if (totalFiles === 0) {
      return 0; // To avoid division by zero
    }
    return ((completedFiles / totalFiles) * 100).toFixed();
  }

}
